-- Revierte video_exclusiones_2017.sql: borra solo sus 105 filas (las preguntas vuelven a mostrar el vídeo de su tema). Sin BEGIN/COMMIT.
DELETE FROM video_exclusiones WHERE pregunta_id IN (2235,2110,2263,2143,2254,2068,2051,2067,2105,2241,2201,2117,2036,2214,2133,2040,2046,2193,2065,2123,2066,2248,2207,2054,2100,2232,2090,2149,2174,2211,2185,2076,2059,2172,2136,2223,2097,2229,2094,2144,2180,2037,2091,2189,2220,2239,2256,2183,2106,2151,2148,2127,2079,2228,2146,2112,2187,2243,2230,2170,2159,2055,2126,2041,2199,2095,2070,2205,2048,2251,2032,2109,2096,2247,2168,2246,2129,2194,2060,2245,2153,2080,2124,2107,2197,2249,2147,2145,2158,2098,2132,2186,2169,2165,2039,2034,2139,2233,2115,2258,2173,2225,2104,2198,2128) AND pregunta_id IN (SELECT id FROM preguntas WHERE "año" = 2017) AND motivo LIKE 'MIR 2017: %';
DO $$ DECLARE r int; BEGIN
  SELECT count(*) INTO r FROM video_exclusiones WHERE pregunta_id IN (SELECT id FROM preguntas WHERE "año" = 2017);
  IF r <> 0 THEN RAISE EXCEPTION 'quedan % exclusiones de 2017', r; END IF;
  RAISE NOTICE 'exclusiones de 2017 borradas; total restante %', (SELECT count(*) FROM video_exclusiones);
END $$;
